<template>
  <q-page class="text-sm text-foreground" data-test="table-explanation-page">
    <SubHeader
      name="table_explanation"
      :on-search="false"
      :label="$t('table_explanation')"
    />
    <div class="table-explanation-body flex flex-col gap-4">
      <div class="flex items-center gap-2 border-b border-border pb-3">
        <q-btn
          flat
          round
          :aria-label="$t('ai_explain_back_to_document')"
          data-test="table-explanation-back"
          @click="back"
        >
          <Icon icon="mdi:arrow-left" class="size-5" />
          <q-tooltip>{{ $t('ai_explain_back_to_document') }}</q-tooltip>
        </q-btn>
        <div class="min-w-0 flex-1">
          <h1 class="m-0 truncate text-lg font-semibold">
            {{ $t('ai_explain_title') }}
          </h1>
          <p
            v-if="explanation"
            class="m-0 truncate text-xs text-muted-foreground"
          >
            {{ explanation.filename || explanation.doc_id }} ·
            {{ explanation.table_name }}
          </p>
        </div>
        <q-btn
          v-if="explanation"
          flat
          no-caps
          color="primary"
          data-test="table-explanation-pipeline"
          @click="insight = 'pipeline'"
        >
          <Icon icon="mdi:transit-connection-variant" class="mr-2 size-4" />{{
            $t('ai_explain_pipeline')
          }}
        </q-btn>
        <q-btn
          v-if="explanation"
          flat
          no-caps
          color="primary"
          data-test="table-explanation-advice"
          @click="insight = 'advice'"
        >
          <Icon icon="mdi:lightbulb-outline" class="mr-2 size-4" />{{
            $t('ai_explain_advice_button')
          }}
        </q-btn>
        <q-btn
          v-if="explanation"
          outline
          no-caps
          data-test="table-explanation-reload"
          @click="load"
        >
          <Icon icon="mdi:refresh" class="mr-2 size-4" />{{
            $t('ai_explain_reload')
          }}
        </q-btn>
      </div>

      <div
        v-if="loading"
        class="flex flex-col items-center gap-2 py-10 text-muted-foreground"
        data-test="table-explanation-loading"
      >
        <q-spinner size="32px" />
        <span class="text-xs">{{ $t('ai_explain_loading') }}</span>
      </div>

      <div
        v-else-if="forbidden"
        class="flex max-w-[640px] flex-col items-start gap-2 p-2"
        :data-test="`table-explanation-forbidden-${forbidden}`"
      >
        <Icon icon="mdi:lock-outline" color="var(--warning)" class="size-7" />
        <!--
        module_off: the organisation has no licence for the module.
        no_access: it has the licence, this user is not enabled yet.
      -->
        <p class="m-0 text-base font-semibold">
          {{
            forbidden === 'module_off'
              ? $t('ai_explain_license_title')
              : $t('ai_explain_user_access_title')
          }}
        </p>
        <p class="m-0 text-muted-foreground">
          {{
            forbidden === 'module_off'
              ? $t('ai_explain_license_required')
              : $t('ai_explain_user_access_required')
          }}
        </p>
        <q-btn
          v-if="forbidden === 'module_off'"
          unelevated
          no-caps
          color="primary"
          class="mt-2"
          data-test="table-explanation-open-modules"
          @click="$router.push(MODULES_ROUTE)"
        >
          <Icon icon="mdi:tune" class="mr-2 size-4" />{{
            $t('ai_explain_open_modules')
          }}
        </q-btn>
      </div>

      <div
        v-else-if="error"
        role="alert"
        class="rounded-md border border-destructive/40 bg-destructive/5 px-3 py-2 text-destructive"
        data-test="table-explanation-error"
      >
        {{ $t('ai_explain_failed') }}
        <span class="ml-1 text-xs text-muted-foreground">{{ error }}</span>
      </div>

      <div
        v-else-if="explanation"
        class="grid grid-cols-1 items-start gap-5 min-[1100px]:grid-cols-[minmax(320px,38%)_minmax(0,1fr)]"
      >
        <!-- left: the document, page by page — the reader sees the raw columns next to the picture they came from -->
        <aside
          class="rounded-lg border border-border bg-muted/40 p-3 min-[1100px]:sticky min-[1100px]:top-3 min-[1100px]:max-h-[calc(100vh-110px)] min-[1100px]:overflow-auto"
          data-test="table-explanation-preview"
        >
          <div class="mb-2 flex items-center gap-1">
            <span class="flex-1 font-semibold">{{
              $t('ai_explain_preview')
            }}</span>
            <q-btn
              flat
              round
              size="sm"
              :disable="page <= 1"
              data-test="table-explanation-prev-page"
              @click="page = Math.max(1, page - 1)"
            >
              <Icon icon="mdi:chevron-left" class="size-5" />
            </q-btn>
            <span
              class="text-xs tabular-nums text-muted-foreground"
              data-test="table-explanation-page-no"
              >{{ page }} / {{ pageCount }}</span
            >
            <q-btn
              flat
              round
              size="sm"
              :disable="page >= pageCount"
              data-test="table-explanation-next-page"
              @click="page = Math.min(pageCount, page + 1)"
            >
              <Icon icon="mdi:chevron-right" class="size-5" />
            </q-btn>
          </div>
          <img
            v-if="pageImageUrl"
            :src="pageImageUrl"
            :alt="`${$t('ai_explain_preview')} ${page}`"
            class="block h-auto w-full rounded-md border border-border bg-white"
            data-test="table-explanation-page-image"
          />
        </aside>

        <!-- right: the explanation, full height, nothing folded away -->
        <section class="min-w-0 rounded-lg border border-border bg-card">
          <AITableExplanationContent :explanation="explanation" />
        </section>
      </div>
    </div>

    <AITableInsightDialog
      v-if="insight"
      :model-value="Boolean(insight)"
      :kind="insight"
      :doc-id="docId"
      :table-name="tableName"
      @update:model-value="insight = null"
    />
  </q-page>
</template>

<script lang="ts">
/**
 * The AI-table explanation as its own page (DOCB-14569).
 *
 * Same content as the "Show" dialog, but with the document preview beside
 * it: raw columns on the right, the page they were read from on the left,
 * and enough room for every section without a scrolling popup. Route
 * `table-explanation` (`:id` = document, `?table=` = table name).
 *
 * One read, the explanation. The processing chain and the KI-Advisor
 * (8–15 s) load only when their buttons are clicked (CORE-6131).
 */
import { defineComponent } from 'vue';
import { Icon } from '@iconify/vue';
import AITableExplanationContent from 'src/components/document/AITableExplanationContent.vue';
import AITableInsightDialog from 'src/components/document/AITableInsightDialog.vue';
import SubHeader from 'src/pages/Settings/Components/Sub-Header.vue';
import {
  MODULES_ROUTE,
  forbiddenReason,
  type ForbiddenReason,
} from 'src/components/document/tableExplanationAccess';
import { DOC2API_URL } from 'src/pages/APIs';
import { useImageAuth } from 'src/composables/useImageAuth';
import { tableExplanationService } from 'src/services';
import type { TableExplanation } from 'src/services/analytics/TableExplanationService';
import { ApiExceptions } from 'src/exceptions/index';
import type { dynamicObj } from 'src/pages/assets';

export default defineComponent({
  name: 'TableExplanationPage',
  components: {
    AITableExplanationContent,
    AITableInsightDialog,
    Icon,
    SubHeader,
  },
  setup() {
    const { tokenQueryParam, refreshTokenParam } = useImageAuth();
    return { tokenQueryParam, refreshTokenParam, MODULES_ROUTE };
  },
  data() {
    return {
      loading: false,
      error: '',
      forbidden: '' as ForbiddenReason | '',
      explanation: null as TableExplanation | null,
      insight: null as 'pipeline' | 'advice' | null,
      page: 1,
    };
  },
  computed: {
    docId(): string {
      return String(this.$route.params.id || '');
    },
    tableName(): string | null {
      const table = this.$route.query.table;
      return typeof table === 'string' && table ? table : null;
    },
    pageCount(): number {
      const pages = Number(this.explanation?.steps?.document?.pages || 0);
      return pages > 0 ? pages : 1;
    },
    /** `/resource/image/{doc}/{page}.png` with the token the image route expects. */
    pageImageUrl(): string {
      if (!this.docId || !this.tokenQueryParam) return '';
      return `${DOC2API_URL}/resource/image/${encodeURIComponent(this.docId)}/${this.page}.png?${this.tokenQueryParam}`;
    },
  },
  watch: {
    '$route.params.id'() {
      void this.load();
    },
    '$route.query.table'() {
      void this.load();
    },
  },
  mounted() {
    void this.load();
  },
  methods: {
    async load() {
      if (!this.docId) return;
      const docId = this.docId;
      const tableName = this.tableName;
      this.loading = true;
      this.error = '';
      this.forbidden = '';
      this.explanation = null;
      this.page = 1;
      try {
        const explanation =
          await tableExplanationService.getDocumentTableExplanation(
            docId,
            tableName,
          );
        // the route may have moved on while we were waiting
        if (this.docId !== docId) return;
        this.explanation = explanation;
      } catch (error) {
        // 403 = the Analytics Dashboard module is off for this org / user —
        // not a failure of the explanation, a door to open in the modules
        const reason = forbiddenReason(error);
        if (reason) {
          this.forbidden = reason;
        } else {
          this.error = ApiExceptions.getErrorMessage(error as dynamicObj);
        }
      } finally {
        this.loading = false;
      }
    },
    back() {
      if (window.history.length > 1) {
        this.$router.back();
        return;
      }
      // opened in its own window from the validation screen: close it
      window.close();
      if (!window.closed) {
        void this.$router.push(`/field_validation_v1/${this.docId}`);
      }
    },
  },
});
</script>

<style scoped>
.table-explanation-body {
  /* not the .flex class: Quasar's flex-wrap would lay the sections side by side */
  flex-wrap: nowrap;
  padding: 12px 24px 24px;
}
</style>
